void ospf6_interface_stop ( struct ospf6_interface * oi ) { struct ospf6_area * oa ; oa = oi -> area ; ospf6_interface_disable ( oi ) ; listnode_delete ( oa -> if_list , oi ) ; oi -> area = NULL ; if ( oa -> if_list -> count == 0 ) { UNSET_FLAG ( oa -> flag , OSPF6_AREA_ENABLE ) ; ospf6_abr_disable_area ( oa ) ; } } 